# More rigorous verification using Floyd-Warshall-like approach for shortest cycles
import sys

n = 14
# Distance matrix
INF = 1000
dist = [[INF]*n for _ in range(n)]
next_node = [[-1]*n for _ in range(n)]

for u,v in edges:
    dist[u][v] = 1
    dist[v][u] = 1
    next_node[u][v] = v
    next_node[v][u] = u

for i in range(n):
    dist[i][i] = 0
    next_node[i][i] = i

# Floyd-Warshall
for k in range(n):
    for i in range(n):
        for j in range(n):
            if dist[i][k] + dist[k][j] < dist[i][j]:
                dist[i][j] = dist[i][k] + dist[k][j]

# For each edge, the shortest cycle containing it is dist[v][u] + 1 where we remove edge (u,v)
# More carefully: for each pair (i,j), shortest cycle through them is dist[i][j] + dist[j][i] but this double counts
# Actually girth is min over all edges (u,v) of: 1 + shortest path from v to u not using edge (u,v)

# Let's compute by checking all simple cycles up to length 5
from itertools import combinations

def check_simple_cycles():
    # Check all combinations of k vertices for k=3,4,5,6
    def is_cycle(verts):
        # Check if they form a cycle in order and all edges exist
        k = len(verts)
        for i in range(k):
            u, v = verts[i], verts[(i+1)%k]
            if v not in adj[u]:
                return False
        # Also need to make sure there are no chords (for it to be a simple cycle of exactly length k)
        # But for finding shortest cycle, we just need ANY cycle
        return True

    # Actually, better: for each starting node, BFS tracking visited
    shortest = INF
    for start in range(n):
        # BFS
        parent = {start: -1}
        q = [start]
        dist_bfs = {start: 0}
        for u in q:
            for v in adj[u]:
                if v == parent.get(u, -2):
                    continue
                if v in dist_bfs:
                    # Found cycle: path from start to u + path from v to start
                    if v != parent[u]:
                        cycle_len = dist_bfs[u] + dist_bfs[v] + 1
                        shortest = min(shortest, cycle_len)
                else:
                    dist_bfs[v] = dist_bfs[u] + 1
                    parent[v] = u
                    q.append(v)
    return shortest

print("Shortest cycle length:", check_simple_cycles())

